import React from 'react';

const DriverMap = ({ driverLocation, driverName, pickupAddress }) => {
  if (!driverLocation || !driverLocation.lat) {
    return (
      <div style={styles.mapPlaceholder}>
        <div>📍 Waiting for driver location...</div>
      </div>
    );
  }

  const googleMapsUrl = `https://www.google.com/maps?q=${driverLocation.lat},${driverLocation.lng}`;

  return (
    <div style={styles.mapContainer}>
      <div style={styles.mapHeader}>
        <span>🚗 {driverName || 'Driver'} is on the way</span>
      </div>
      <div style={styles.mapPreview}>
        <div style={styles.mapCoordinates}>
          <div>📍 Latitude: {driverLocation.lat.toFixed(6)}</div>
          <div>📍 Longitude: {driverLocation.lng.toFixed(6)}</div>
          <div>🕐 Last update: {new Date(driverLocation.lastUpdate).toLocaleTimeString()}</div>
        </div>
        <div style={styles.mapLink}>
          <a href={googleMapsUrl} target="_blank" rel="noopener noreferrer" style={styles.mapLinkButton}>
            🔍 Open in Google Maps
          </a>
        </div>
      </div>
    </div>
  );
};

const styles = {
  mapContainer: {
    backgroundColor: '#f0fdf4',
    borderRadius: '8px',
    padding: '12px',
    marginTop: '10px',
    border: '1px solid #bbf7d0'
  },
  mapHeader: {
    fontWeight: 'bold',
    marginBottom: '8px',
    color: '#166534'
  },
  mapPreview: {
    fontSize: '12px',
    color: '#374151'
  },
  mapCoordinates: {
    marginBottom: '8px',
    padding: '8px',
    backgroundColor: '#f9fafb',
    borderRadius: '6px'
  },
  mapLink: {
    marginTop: '8px'
  },
  mapLinkButton: {
    display: 'inline-block',
    backgroundColor: '#3b82f6',
    color: 'white',
    padding: '6px 12px',
    borderRadius: '6px',
    textDecoration: 'none',
    fontSize: '12px'
  },
  mapPlaceholder: {
    backgroundColor: '#f3f4f6',
    borderRadius: '8px',
    padding: '20px',
    textAlign: 'center',
    color: '#6b7280',
    marginTop: '10px'
  }
};

export default DriverMap;
